// The knowledge base and its `hitld kb` tool (design part 8.5): search with glossary expansion, the
// generated index and decisions.md, staleness, links and the check that runs at merge.
//
// The notes are markdown files under kb/ in git, the source of truth (design 8.2). Their front
// matter is read with the files backend's reader, which takes data only (design 3.4), and checked
// against schemas/kb-note.schema.json. Nothing here edits a note: `kb index` writes only the
// generated files, and every other command reads.
//
// Generated, never notes: a file named index.md anywhere under kb/ (the index, and
// kb/areas/<area>/index.md when it is split by area) and kb/decisions.md.

import { spawnSync } from 'node:child_process';
import { existsSync, readdirSync, rmSync } from 'node:fs';
import { join, posix } from 'node:path';
import { parseItem } from '../tracker/files/frontmatter.mjs';
import {
  insidePath,
  isRegularFile,
  mkdirInside,
  readNoFollow,
  writeNoFollow,
} from '../tracker/files/safe.mjs';
import { policyDefaults } from '../policy/policy.mjs';
import { schemas } from '../schema/registry.mjs';

/** Where the public knowledge base lives, relative to the repository root. */
export const KB_DIR = 'kb';

/** The line every generated file carries; a generated index file without it is never removed. */
export const GENERATED_MARK = '<!-- Generated by `hitld kb index`. Do not edit by hand. -->';

/** A token estimate: characters / 4. Budgets are coarse, so the estimate need not be exact. @param {string} text */
export const tokensOf = (text) => Math.ceil(text.length / 4);

/**
 * @typedef {object} Note
 * @property {string} path the path relative to kb/, with forward slashes
 * @property {string} text the whole file
 * @property {Record<string, any> | null} data the front matter, or null when it has none
 * @property {string} body
 * @property {string[]} errors problems reading the front matter
 *
 * @typedef {{ kind: string, path: string, message: string }} Problem
 *
 * @typedef {object} KnowledgeBase
 * @property {string} repoRoot
 * @property {boolean} exists whether kb/ is there
 * @property {Note[]} notes by path
 * @property {Map<string, string>} generated the generated files on disk, path relative to kb/ to text
 * @property {Problem[]} problems files that could not be read
 * @property {string[][]} glossary each term with its synonyms, lower-case
 *
 * @typedef {{ indexTokensMax: number, noteTokensMax: number, maxAgeUnsourced: number }} Budgets
 */

/** The budgets from a loaded policy (its kb section), or the defaults. @param {Record<string, any> | null | undefined} policy @returns {Budgets} */
export function budgetsOf(policy) {
  const kb = policy?.kb ?? policyDefaults().kb;
  return {
    indexTokensMax: kb.index_tokens_max,
    noteTokensMax: kb.note_tokens_max,
    maxAgeUnsourced: kb.max_age_unsourced,
  };
}

/** @param {string} rel a path relative to kb/ */
const isGenerated = (rel) => posix.basename(rel) === 'index.md' || rel === 'decisions.md';

/**
 * Read every note under kb/. A symbolic link is reported and never followed.
 * @param {string} repoRoot
 * @returns {KnowledgeBase}
 */
export function loadKnowledgeBase(repoRoot) {
  const kbDir = insidePath(repoRoot, KB_DIR);
  /** @type {KnowledgeBase} */
  const kb = {
    repoRoot,
    exists: existsSync(kbDir),
    notes: [],
    generated: new Map(),
    problems: [],
    glossary: [],
  };
  if (!kb.exists) return kb;
  /** @param {string} dir @param {string} rel */
  const walk = (dir, rel) => {
    for (const d of readdirSync(dir, { withFileTypes: true }).sort((a, b) =>
      a.name.localeCompare(b.name),
    )) {
      if (d.name.startsWith('.')) continue;
      const path = rel ? `${rel}/${d.name}` : d.name;
      const full = join(dir, d.name);
      if (d.isSymbolicLink()) {
        kb.problems.push({
          kind: 'unreadable',
          path: `${KB_DIR}/${path}`,
          message: 'is a symbolic link; the knowledge base does not follow links',
        });
      } else if (d.isDirectory()) {
        walk(full, path);
      } else if (d.name.endsWith('.md') && isRegularFile(full)) {
        const text = readNoFollow(full);
        if (isGenerated(path)) {
          kb.generated.set(path, text);
          continue;
        }
        const parsed = parseItem(text);
        kb.notes.push({ path, text, data: parsed.data, body: parsed.body, errors: parsed.errors });
      }
    }
  };
  walk(kbDir, '');
  const glossary = kb.notes.find((n) => n.path === 'glossary.md');
  if (glossary) kb.glossary = parseGlossary(glossary.body);
  return kb;
}

/**
 * The glossary's terms: list lines of the form `- **term**: synonym, synonym`. Links and
 * parenthesized remarks on the line are not synonyms.
 * @param {string} body
 * @returns {string[][]}
 */
export function parseGlossary(body) {
  /** @type {string[][]} */
  const out = [];
  for (const line of body.split('\n')) {
    const m = /^\s*[-*]\s+(.+)$/.exec(line);
    if (!m) continue;
    const plain = m[1]
      .replace(/\[([^\]]*)\]\([^)]*\)/g, '')
      .replace(/\([^)]*\)/g, '')
      .replace(/[*_`]/g, '');
    const colon = plain.indexOf(':');
    if (colon < 0) continue;
    const words = [plain.slice(0, colon), ...plain.slice(colon + 1).split(/[,;]/)]
      .map((w) => w.trim().toLowerCase())
      .filter(Boolean);
    if (words.length > 1) out.push([...new Set(words)]);
  }
  return out;
}

/** @param {Note} n @returns {string[]} */
const listOf = (n, /** @type {string} */ key) => {
  const v = n.data?.[key];
  return Array.isArray(v) ? v.map(String) : typeof v === 'string' && v ? [v] : [];
};

/**
 * The notes other notes retire, as paths relative to kb/, each with the note that retires it.
 * @param {KnowledgeBase} kb @returns {Map<string, string>}
 */
export function supersededNotes(kb) {
  /** @type {Map<string, string>} */
  const out = new Map();
  for (const n of kb.notes) {
    for (const s of listOf(n, 'supersedes')) out.set(posix.normalize(s), n.path);
  }
  return out;
}

/** @param {string} s */
const escapeRegExp = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/**
 * A search term with its glossary synonyms: every glossary entry that names the term, in either
 * place, adds its other words.
 * @param {string} term @param {string[][]} glossary
 */
export function expandTerm(term, glossary) {
  const t = term.toLowerCase();
  const words = new Set([t]);
  for (const entry of glossary) if (entry.includes(t)) entry.forEach((w) => words.add(w));
  return [...words];
}

/**
 * Search the notes (the grep+index retriever, design 8.5): each term, expanded through the glossary,
 * matches at the start of a word in the note's path, summary, areas, tags or body. Ranked by how
 * many terms match, then by matches in the front matter (weighted), then in the body. Superseded
 * notes are left out.
 * @param {KnowledgeBase} kb
 * @param {{ terms: string[], area?: string, tag?: string }} q
 */
export function searchKnowledgeBase(kb, { terms, area, tag }) {
  const superseded = supersededNotes(kb);
  const groups = terms.map((t) => ({ term: t, words: expandTerm(t, kb.glossary) }));
  const results = [];
  for (const n of kb.notes) {
    if (superseded.has(n.path)) continue;
    const areas = listOf(n, 'areas');
    const tags = listOf(n, 'tags');
    if (area && !areas.includes(area)) continue;
    if (tag && !tags.includes(tag)) continue;
    const head = [n.path, String(n.data?.summary ?? ''), ...areas, ...tags].join('\n');
    let score = 0;
    /** @type {string[]} */
    const matched = [];
    for (const g of groups) {
      const re = new RegExp(`\\b(?:${g.words.map(escapeRegExp).join('|')})`, 'gi');
      const inHead = head.match(re)?.length ?? 0;
      const inBody = n.body.match(re)?.length ?? 0;
      if (!inHead && !inBody) continue;
      matched.push(g.term);
      score += 3 * inHead + Math.min(inBody, 20);
    }
    if (!matched.length) continue;
    results.push({
      path: `${KB_DIR}/${n.path}`,
      summary: n.data?.summary ?? null,
      areas,
      tags,
      matched,
      score: matched.length * 100 + score,
    });
  }
  results.sort((a, b) => b.score - a.score || a.path.localeCompare(b.path));
  return {
    expanded: Object.fromEntries(groups.map((g) => [g.term, g.words.filter((w) => w !== g.term)])),
    results,
  };
}

/** @param {Note} n */
const isPublic = (n) => n.data?.classification === undefined || n.data.classification === 'public';

/** @param {string} from a path relative to kb/ of the file holding the link @param {string} to */
const hrefFrom = (from, to) => posix.relative(posix.dirname(from), to) || posix.basename(to);

/**
 * The generated index files, path relative to kb/ to text. One index while it fits
 * kb.index_tokens_max; above it, a top-level index of areas (and of the notes with no area) and
 * kb/areas/<area>/index.md for each area. A superseded note is left out, and so is a note above
 * public: the public index never lists one (design 8.3).
 * @param {KnowledgeBase} kb @param {Budgets} budgets
 * @returns {{ files: Map<string, string>, split: boolean, tokens: number }}
 */
export function buildIndex(kb, budgets) {
  const superseded = supersededNotes(kb);
  /** @type {Map<string, Note[]>} */
  const byArea = new Map();
  /** @type {Note[]} */
  const general = [];
  for (const n of kb.notes) {
    if (superseded.has(n.path) || !isPublic(n) || typeof n.data?.summary !== 'string') continue;
    const first = listOf(n, 'areas')[0];
    if (!first) general.push(n);
    else byArea.set(first, [...(byArea.get(first) ?? []), n]);
  }
  const areas = [...byArea.keys()].sort();
  /** @param {string} at @param {Note} n */
  const line = (at, n) => `- [${n.path}](${hrefFrom(at, n.path)}): ${n.data?.summary}`;
  const head = (/** @type {string} */ title) => [`# ${title}`, '', GENERATED_MARK, ''];
  /** @param {string} title @param {Note[]} notes */
  const section = (title, notes) => [
    `## ${title}`,
    '',
    ...notes.map((n) => line('index.md', n)),
    '',
  ];

  const whole = [
    ...head('Knowledge base index'),
    ...(general.length ? section('General', general) : []),
    ...areas.flatMap((a) => section(a, /** @type {Note[]} */ (byArea.get(a)))),
  ].join('\n');
  const tokens = tokensOf(whole);
  if (tokens <= budgets.indexTokensMax || areas.length < 2) {
    return { files: new Map([['index.md', whole]]), split: false, tokens };
  }
  /** @type {Map<string, string>} */
  const files = new Map();
  files.set(
    'index.md',
    [
      ...head('Knowledge base index'),
      'The index is split by area: read the index of the area you need.',
      '',
      ...(general.length ? section('General', general) : []),
      '## Areas',
      '',
      ...areas.map(
        (a) =>
          `- [${a}](areas/${a}/index.md): ${/** @type {Note[]} */ (byArea.get(a)).length} note(s)`,
      ),
      '',
    ].join('\n'),
  );
  for (const a of areas) {
    const at = `areas/${a}/index.md`;
    files.set(
      at,
      [
        ...head(`Knowledge base index: ${a}`),
        .../** @type {Note[]} */ (byArea.get(a)).map((n) => line(at, n)),
        '',
      ].join('\n'),
    );
  }
  return { files, split: true, tokens };
}

/**
 * @typedef {{ id: string, title: string, answer: string, answered_at?: string }} DecisionLine
 * @typedef {{ id: string, rule: string }} PrecedentLine
 */

/**
 * kb/decisions.md: the answered decisions and the active precedents, pointers only (design 8.3:
 * the knowledge base explains, the tracker records).
 * @param {DecisionLine[]} decisions @param {PrecedentLine[]} precedents
 */
export function buildDecisions(decisions, precedents) {
  const byNumber = (/** @type {{ id: string }} */ a, /** @type {{ id: string }} */ b) =>
    a.id.localeCompare(b.id, 'en', { numeric: true });
  const oneLine = (/** @type {string} */ s) => s.replace(/\s+/g, ' ').trim();
  return [
    '# Decisions',
    '',
    GENERATED_MARK,
    '',
    'Answered decisions and active precedents. The tracker records them; read the item or the precedent for the reasoning.',
    '',
    '## Decisions',
    '',
    ...(decisions.length
      ? [...decisions]
          .sort(byNumber)
          .map(
            (d) =>
              `- ${d.id}${d.answered_at ? ` (${d.answered_at.slice(0, 10)})` : ''}: ${oneLine(d.title)}. Answer: ${oneLine(d.answer)}`,
          )
      : ['None answered yet.']),
    '',
    '## Precedents',
    '',
    ...(precedents.length
      ? [...precedents].sort(byNumber).map((p) => `- ${p.id}: ${oneLine(p.rule)}`)
      : ['None active.']),
    '',
  ].join('\n');
}

/**
 * Write the generated files and remove generated index files that are no longer produced (an
 * index that was split and fits again). A file without the generated mark is never removed.
 * @param {KnowledgeBase} kb @param {Map<string, string>} files
 * @returns {{ written: string[], removed: string[] }}
 */
export function writeGenerated(kb, files) {
  const written = [];
  const removed = [];
  for (const [rel, text] of files) {
    if (kb.generated.get(rel) === text) continue;
    const dir = posix.dirname(`${KB_DIR}/${rel}`);
    mkdirInside(kb.repoRoot, dir);
    writeNoFollow(insidePath(kb.repoRoot, `${KB_DIR}/${rel}`), text);
    written.push(`${KB_DIR}/${rel}`);
  }
  for (const [rel, text] of kb.generated) {
    if (files.has(rel) || rel === 'decisions.md' || !text.includes(GENERATED_MARK)) continue;
    rmSync(insidePath(kb.repoRoot, `${KB_DIR}/${rel}`));
    removed.push(`${KB_DIR}/${rel}`);
  }
  return { written, removed };
}

/** @param {string} cwd @param {string[]} args */
function git(cwd, args) {
  const r = spawnSync('git', args, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
  return { status: r.status, out: (r.stdout ?? '').trim(), err: (r.stderr ?? '').trim() };
}

/**
 * Notes whose sources changed since `checked_at` (design 8.5): `git diff <checked_at> HEAD --
 * <sources>` is not empty. A `checked_at` that is not a commit reachable from HEAD counts as
 * stale, and so does a sourced note with none. A note with no sources is stale
 * kb.max_age_unsourced days after its `checked` date. Superseded notes are left out.
 * @param {KnowledgeBase} kb @param {Budgets} budgets @param {{ now?: number }} [options]
 * @returns {{ stale: { path: string, reason: 'changed' | 'unreachable' | 'unchecked' | 'old', message: string, changed?: string[] }[], problems: Problem[] }}
 */
export function staleNotes(kb, budgets, { now = Date.now() } = {}) {
  const superseded = supersededNotes(kb);
  const stale = [];
  /** @type {Problem[]} */
  const problems = [];
  const head = git(kb.repoRoot, ['rev-parse', '--verify', '--quiet', 'HEAD']);
  for (const n of kb.notes) {
    if (!n.data || superseded.has(n.path)) continue;
    const path = `${KB_DIR}/${n.path}`;
    const sources = listOf(n, 'sources');
    const at = typeof n.data.checked_at === 'string' ? n.data.checked_at : '';
    if (sources.length) {
      if (!at) {
        stale.push({
          path,
          reason: /** @type {const} */ ('unchecked'),
          message: 'has sources but no checked_at',
        });
        continue;
      }
      const reachable =
        head.status === 0 &&
        /^[0-9a-f]{7,64}$/.test(at) &&
        git(kb.repoRoot, ['rev-parse', '--verify', '--quiet', `${at}^{commit}`]).status === 0 &&
        git(kb.repoRoot, ['merge-base', '--is-ancestor', at, 'HEAD']).status === 0;
      if (!reachable) {
        stale.push({
          path,
          reason: /** @type {const} */ ('unreachable'),
          message: `checked_at ${at} is not a commit reachable from HEAD`,
        });
        continue;
      }
      const diff = git(kb.repoRoot, [
        'diff',
        '--name-only',
        at,
        'HEAD',
        '--',
        ...sources.map((s) => `:(glob)${s}`),
      ]);
      if (diff.status !== 0) {
        problems.push({
          kind: 'front-matter',
          path,
          message: `its sources could not be compared: ${diff.err.split('\n')[0]}`,
        });
        continue;
      }
      if (diff.out) {
        const changed = diff.out.split('\n');
        stale.push({
          path,
          reason: /** @type {const} */ ('changed'),
          message: `stale since ${at}: ${changed.length} source file(s) changed; verify against sources`,
          changed: changed.slice(0, 20),
        });
      }
      continue;
    }
    if (!budgets.maxAgeUnsourced) continue;
    const checked = typeof n.data.checked === 'string' ? Date.parse(n.data.checked) : NaN;
    if (Number.isNaN(checked)) {
      stale.push({
        path,
        reason: /** @type {const} */ ('unchecked'),
        message: 'has no sources and no checked date',
      });
    } else if ((now - checked) / 86_400_000 > budgets.maxAgeUnsourced) {
      stale.push({
        path,
        reason: /** @type {const} */ ('old'),
        message: `has no sources and was checked ${n.data.checked}, more than ${budgets.maxAgeUnsourced} days ago`,
      });
    }
  }
  return { stale, problems };
}

/**
 * The link targets in a note's body (inline and reference links, outside code) and in its
 * front-matter `links`, each as written.
 * @param {Note} n @returns {string[]}
 */
function linkTargets(n) {
  const prose = n.body
    .replace(/^(```|~~~)[^\n]*\n[\s\S]*?^\1[^\n]*$/gm, '')
    .replace(/`[^`\n]*`/g, '');
  const out = [];
  for (const m of prose.matchAll(/!?\[[^\]\n]*\]\(\s*<?([^)\s>]+)>?(?:\s+"[^"]*")?\s*\)/g)) {
    out.push(m[1]);
  }
  for (const m of prose.matchAll(/^\s{0,3}\[[^\]\n]+\]:\s*<?(\S+?)>?(?:\s|$)/gm)) out.push(m[1]);
  return [...out, ...listOf(n, 'links')];
}

/**
 * Broken links, and links to superseded notes (design 8.5). A link is relative to the note; one
 * starting with / is relative to the repository root; a URL or an anchor alone is not checked.
 * @param {KnowledgeBase} kb @returns {Problem[]}
 */
export function linkProblems(kb) {
  const superseded = supersededNotes(kb);
  /** @type {Problem[]} */
  const out = [];
  for (const n of kb.notes) {
    const from = `${KB_DIR}/${n.path}`;
    for (const raw of new Set(linkTargets(n))) {
      if (/^[a-z][a-z0-9+.-]*:/i.test(raw) || raw.startsWith('#')) continue;
      let target = raw.replace(/[#?].*$/, '');
      try {
        target = decodeURIComponent(target);
      } catch {
        // Left as written: a bad escape is then a broken link.
      }
      const resolved = target.startsWith('/')
        ? posix.normalize(target.slice(1))
        : posix.normalize(posix.join(posix.dirname(from), target));
      if (resolved === '..' || resolved.startsWith('../')) {
        out.push({ kind: 'broken-link', path: from, message: `${raw} leaves the repository` });
        continue;
      }
      if (!existsSync(join(kb.repoRoot, resolved))) {
        out.push({ kind: 'broken-link', path: from, message: `${raw}: no such file` });
        continue;
      }
      const inKb = resolved.startsWith(`${KB_DIR}/`) ? resolved.slice(KB_DIR.length + 1) : null;
      const by = inKb ? superseded.get(inKb) : undefined;
      if (by && !superseded.has(n.path)) {
        out.push({
          kind: 'superseded-link',
          path: from,
          message: `${raw} is superseded by ${KB_DIR}/${by}; link to that instead`,
        });
      }
    }
  }
  return out;
}

/**
 * Everything `hitld kb check` checks (design 8.5): the front matter against its schema, the size
 * budgets, links, staleness, and whether the generated files are current.
 *
 * Errors fail the check, and the merge: a note with no or bad front matter, a note above its
 * budget, a broken link or one to a superseded note. A note above the repository's ceiling is the
 * commit guard's to refuse (design 10.3); the index leaves out any note above public.
 * Warnings do not: a stale note (the curator re-verifies those after merges, and `checked_at` is
 * stamped at merge), an index or decisions.md that is not current (regenerated by `hitld kb
 * index`; two branches that each change notes would otherwise refuse each other), and an index
 * over its budget even after splitting by area.
 *
 * @param {KnowledgeBase} kb @param {Budgets} budgets
 * @param {{ now?: number, decisions?: { decisions: DecisionLine[], precedents: PrecedentLine[] } }} [options]
 *   decisions: what decisions.md should list; without it, decisions.md is not compared
 */
export function checkKnowledgeBase(kb, budgets, options = {}) {
  /** @type {Problem[]} */
  const errors = [...kb.problems];
  /** @type {(Problem & { reason?: string, changed?: string[] })[]} */
  const warnings = [];
  const registry = schemas();
  for (const n of kb.notes) {
    const path = `${KB_DIR}/${n.path}`;
    if (!n.data) {
      errors.push({ kind: 'front-matter', path, message: 'has no front matter' });
    } else {
      for (const e of n.errors) errors.push({ kind: 'front-matter', path, message: e });
      for (const e of registry.validate('kb-note', n.data)) {
        errors.push({
          kind: 'front-matter',
          path,
          message: `${e.path || '(front matter)'} ${e.message}`,
        });
      }
    }
    const tokens = tokensOf(n.text);
    if (tokens > budgets.noteTokensMax) {
      errors.push({
        kind: 'size',
        path,
        message: `is about ${tokens} tokens, over kb.note_tokens_max (${budgets.noteTokensMax}): split it into notes of one topic each`,
      });
    }
  }
  errors.push(...linkProblems(kb));
  const stale = staleNotes(kb, budgets, { now: options.now });
  errors.push(...stale.problems);
  for (const s of stale.stale) warnings.push({ kind: 'stale', ...s });

  const index = buildIndex(kb, budgets);
  const current = [...index.files].every(([rel, text]) => kb.generated.get(rel) === text);
  const leftover = [...kb.generated].some(
    ([rel, text]) =>
      rel !== 'decisions.md' && !index.files.has(rel) && text.includes(GENERATED_MARK),
  );
  if (kb.notes.length && (!current || leftover)) {
    warnings.push({
      kind: 'index',
      path: `${KB_DIR}/index.md`,
      message: 'is not current with the notes; run hitld kb index',
    });
  }
  if (index.split) {
    for (const [rel, text] of index.files) {
      const t = tokensOf(text);
      if (t > budgets.indexTokensMax) {
        warnings.push({
          kind: 'index',
          path: `${KB_DIR}/${rel}`,
          message: `is about ${t} tokens, over kb.index_tokens_max (${budgets.indexTokensMax}) even after splitting by area`,
        });
      }
    }
  }
  if (options.decisions && kb.exists) {
    const want = buildDecisions(options.decisions.decisions, options.decisions.precedents);
    if (kb.generated.get('decisions.md') !== want) {
      warnings.push({
        kind: 'decisions',
        path: `${KB_DIR}/decisions.md`,
        message: 'is not current with the tracker; run hitld kb index',
      });
    }
  }
  return { ok: errors.length === 0, errors, warnings, stale: stale.stale.length };
}
